export function maximum(v,key){return v[{hp:'maxHp',stamina:'maxStamina',mana:'maxMana'}[key]]||100}
export function upgradeStat(p,v,key){if(!['hp','stamina','mana'].includes(key)||!(p.pendingLevels>0))return false;const field={hp:'maxHp',stamina:'maxStamina',mana:'maxMana'}[key];v[field]=maximum(v,key)+10;for(const resource of ['hp','stamina','mana'])v[resource]=maximum(v,resource);p.pendingLevels--;return true}
export function regenerate(v,dt,{campfire=false,multiplier=1,manaMultiplier=1,healthAllowed=true,zoneMultiplier=1}={}){const hpRate=(campfire?11.5:.5)*multiplier*zoneMultiplier;if(healthAllowed)v.hp=Math.min(maximum(v,'hp'),v.hp+hpRate*dt);v.mana=Math.min(maximum(v,'mana'),v.mana+hpRate*2.16*manaMultiplier*dt)}
export function drinkAle(v){v.hp=Math.min(maximum(v,'hp'),v.hp+45);v.stamina=maximum(v,'stamina');v.mana=Math.min(maximum(v,'mana'),v.mana+maximum(v,'mana')*.5)}
